// Bound the body's whole short segment, not just its endpoint: a grazing corner can lie between samples.
let to=goal-me;let dist=length(to);let direct=safe2(to);var clear=dist<20.0;let steps=max(1u,u32(ceil(dist*8.0)));let sweep=abs(to)*(.5/f32(steps));
for(var s=1u;clear&&s<=steps;s++){let q=me+to*((f32(s)-.5)/f32(steps));if(blocked(vec3f(q.x,.36,q.y),vec3f(.2+sweep.x,.29,.2+sweep.y))){clear=false;}}
